  if(ios)fullHeight=Math.max(fullHeight,h,screenFits?sh:0);else fullHeight=h;
  root.style.setProperty('--planner-full-height',Math.round(fullHeight)+'px');
  const unzoomed=!v||Math.abs(v.scale-1)<0.05;
  const vh=unzoomed&&v&&v.height>0?Math.min(h,v.height):h;
  const top=unzoomed&&v?Math.max(0,Math.min(h-vh,v.offsetTop||0)):0;
  const gap=Math.max(0,h-vh-top);
  const active=document.activeElement;
  const keyboard=unzoomed&&(h-vh>100)&&!!active?.matches('input:not([type=checkbox]):not([type=radio]):not([type=range]):not([type=color]):not([type=file]),textarea,[contenteditable=true]');
  const set=(key,value)=>{const px=Math.round(value)+'px';if(root.style.getPropertyValue(key)!==px)root.style.setProperty(key,px)};
  set('--planner-layout-height',h);set('--planner-vv-height',vh);set('--planner-vv-top',top);set('--planner-vv-bottom',gap);
