function categoryType(c){return c?.wishlist_owner?'wish':c?.system_type||({'Наши дела':'task','Что посмотреть':'movie','Куда сходить':'place','Покупки':'shopping','Путешествия':'travel','Календарь':'calendar','Наши идеи':'idea'}[c?.name]||'custom')}
