const purgingRecords=new Set();
async function purgeRecord(r){
 if(purgingRecords.has(r.id)||lifecycleBusy.has(r.id))return;
 purgingRecords.add(r.id);
 try{
  if(!await recordConfirm(r,'purge',()=>api('items/'+r.id+'/lifecycle','PUT',{action:'purge',version:r.version})))return;
  if(loading)await refreshTask;
  state.trashItems=(state.trashItems||[]).filter(x=>x.id!==r.id);void persistVault();
  if(!undoBar.hidden)undoBar.hidden=true;
  await refresh();haptic(true);
  if($('libraryDialog').open&&libraryMode==='trash')await openLibrary('trash');
 }catch(e){if(e.status===409||e.status===404){await refresh();if($('libraryDialog').open&&libraryMode==='trash')await openLibrary('trash')}showMessage(e.message||'Не удалось удалить запись')}
 finally{purgingRecords.delete(r.id)}
}
let libraryMode='';const lifecycleBusy=new Set();async function life(r,action,confirm=false){if(lifecycleBusy.has(r.id)||purgingRecords.has(r.id))return;lifecycleBusy.add(r.id);try{const run=()=>api('items/'+r.id+'/lifecycle','PUT',{action,version:r.version});if(confirm){if(!await recordConfirm(r,action,run))return}else await run();if(loading)await refreshTask;await refresh();haptic(true);if(action==='archive'||action==='trash')offerUndo(r.id,action);if($('libraryDialog').open)await openLibrary(libraryMode)}catch(e){await refresh();showMessage(e.message||'Не удалось изменить запись')}finally{lifecycleBusy.delete(r.id)}}
