function inboxGreeting(r){return r.body==="🐱 Cat's planner — ваши общие планы и желания."}
function inboxParts(body){const text=String(body||'');const m=text.match(/^(?:[\p{Extended_Pictographic}\uFE0F\u200D]+\s*)?(Обновление[^:]*|Добавлена запись|Выполнено|Изменена запись|Возвращено в планы|Удалена запись|В корзину|В архив|Восстановлено|Возвращено из архива|Новый комментарий|Добавлена важная дата):\s*(.*)$/u);return m?{kind:m[1],detail:m[2]}:{kind:'Уведомление',detail:text};}
