async function openLibrary(mode){libraryMode=mode;const root=$('libraryRows');$('libraryTitle').textContent=({archive:'Архив',trash:'Корзина',history:'История изменений',inbox:'Уведомления'})[mode];root.replaceChildren(node('p','Загрузка…','meta'));if(!$('libraryDialog').open)$('libraryDialog').showModal();try{if(mode==='archive'||mode==='trash'){const rows=mode==='archive'?state.archivedItems:state.trashItems;root.replaceChildren();for(const r of rows||[])root.append(archiveCard(r,mode))}else{const data=await api(mode);if(libraryMode!==mode||!$('libraryDialog').open)return;root.replaceChildren();const rows=mode==='inbox'?data.rows.filter(r=>!inboxGreeting(r)):data.rows;if(mode==='inbox'){const toolbar=node('div',undefined,'inbox-toolbar');if(rows.filter(r=>!r.read_at).length>1)toolbar.append(btn('Прочитать все',()=>inboxAction('inbox','PUT',{}),'secondary'));if(toolbar.children.length)root.append(toolbar);for(const r of rows)root.append(inboxRecord(r))}else for(const r of rows){const e=sectionCard(r.title);e.classList.add('library-record');e.append(node('p',r.action+' · '+(r.actor?person(r.actor):'Система')+' · '+local(r.created_at),'meta'));root.append(e)}if(!rows.length){if(mode==='inbox'){const empty=node('div',undefined,'empty-state hf-inbox-empty');empty.append(lineIcon('bell'),node('strong','Всё прочитано'),node('small','Можно отдыхать 🐾'));root.append(empty)}else root.append(node('p','Пока пусто','meta'))}}if(!root.children.length)root.append(node('p','Пока пусто','meta'))}catch(e){root.replaceChildren(node('p',e.message))}}

