const collapsedMemory=new Map();function collapseWidget(k,el){const key='cats-collapse-'+state.uid+'-'+k;let closed=collapsedMemory.get(key)||false;try{closed=localStorage.getItem(key)==='1'||(localStorage.getItem(key)===null&&closed)}catch{}const details=node('details',undefined,'clean-widget');details.open=!closed;const summary=node('summary',widgets[k][1]);if(k==='today'){const heading=el.querySelector('h3');if(heading){const label=node('span',undefined,'hf5-plan-heading');label.append(lineIcon(heading.dataset.icon||'calendar'),node('span',heading.textContent));summary.replaceChildren(label);}}details.append(summary);const content=node('div',undefined,'widget-body');for(const child of [...el.childNodes])content.append(child);const heading=content.querySelector(k==='today'?'h3':k==='pinned'?'h2':'none');if(heading)heading.remove();details.append(content);details.ontoggle=()=>{collapsedMemory.set(key,!details.open);try{localStorage.setItem(key,details.open?'0':'1')}catch{}};el.replaceChildren(details)}
