function vaultDb(){return new Promise((resolve,reject)=>{const r=indexedDB.open('cats-planner-vault',1);r.onupgradeneeded=()=>r.result.createObjectStore('vault');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)})}
