async function unlockVault(uid,record,password){const salt=new Uint8Array(record.salt),key=await vaultDerive(password,salt);const bytes=await crypto.subtle.decrypt({name:'AES-GCM',iv:record.iv,additionalData:new TextEncoder().encode('cats-vault:'+uid)},key,record.cipher);const data=JSON.parse(new TextDecoder().decode(bytes));if(Number(data.state?.uid)!==uid||!Array.isArray(data.pending)||!Array.isArray(data.drafts))throw Error('Копия другого аккаунта');if(state.generation&&data.state.generation!==state.generation)throw Error('Копия предыдущего поколения базы. Удалите её в настройках.');vaultKey=key;vaultUid=uid;vaultSalt=salt;for(const [k,v] of data.drafts)editorDrafts.set(k,v);for(const [k,v] of data.pending)pendingWrites.set(k,v);return data.state}
async function offerVaultUnlock(){if(vaultUnlockBusy||!crypto.subtle||!localUid())return;vaultUnlockBusy=true;try{const uid=localUid(),r=await vaultAccess('readonly',uid);if(!r)return;const password=await passwordDialog('Открыть офлайн-копию','Локальная копия может содержать устаревшие записи. Для отправки изменений потребуется интернет и действующая авторизация приложения.');if(!password)return;state=await unlockVault(uid,r,password);applyPrefs();cat=visibleCategories()[0]?.id??null;go('home');connectionState('Офлайн-копия · изменения партнёра пока недоступны');$('error').textContent='';}catch{await glassNotice('Не удалось открыть локальную копию. Проверьте пароль.')}finally{vaultUnlockBusy=false}}
async function configureVault(){if(!state.uid||!crypto.subtle){await glassNotice('Нужен вход в приложение и защищённое соединение.');return}try{const uid=Number(state.uid);const existing=await vaultAccess('readonly',uid);if(existing){const password=await passwordDialog('Открыть локальную копию','Введите ранее выбранный пароль. Сохранённая очередь будет восстановлена.');if(!password)return;await unlockVault(uid,existing,password);await persistVault();await glassNotice('Локальная копия открыта.');if(navigator.onLine)await retryPending();return}const password=await passwordDialog('Защищённая локальная копия','Записи будут храниться зашифрованными на этом устройстве. Запомните пароль — восстановить его невозможно.');if(!password)return;const repeated=await passwordDialog('Повторите пароль','Проверьте пароль перед включением локальной копии.');if(password!==repeated){await glassNotice('Пароли не совпадают. Локальная копия не создана.');return}vaultSalt=crypto.getRandomValues(new Uint8Array(16));vaultKey=await vaultDerive(password,vaultSalt);vaultUid=uid;if(!await persistVault())throw Error('Не удалось сохранить копию');await glassNotice('Локальная копия включена. После перезапуска потребуется пароль.')}catch{await glassNotice('Не удалось открыть или сохранить локальную копию. Проверьте пароль и доступность хранилища.')}}
