async function resolveWriteConflict(id,p,remote){const choice=await confirmSheet({heading:'Конфликт синхронизации',title:'Запись изменена партнёром',subject:'Ваша версия: '+p.data.title,detail:'На сервере: '+remote.title+'. Серверная версия не будет перезаписана. Можно сохранить свою отдельной записью или удалить только локальное изменение.',icon:'history',vertical:true,choices:[{label:'Сохранить отдельной записью',value:'copy',primary:true,run:async()=>{if(p.generation!==state.generation)throw Error('Очередь предыдущего поколения');let data={...p.data,version:0,request_id:id};if(data.photo?.startsWith('storage:')){if(remote.photo!==data.photo)throw Error('Исходная обложка изменена. Сохраните запись вручную.');data.photo=(await api(p.path+'/photo')).photo}if(data.ps_photos?.some(x=>x.startsWith('storage:'))){const g=await api(p.path+'/gallery');data.ps_photos=data.ps_photos.map(x=>{if(!x.startsWith('storage:'))return x;const idx=(remote.ps_photos||[]).indexOf(x);if(idx<0||!g.photos?.[idx])throw Error('Одно из исходных фото изменено. Черновик сохранён.');return g.photos[idx]})}await api('items','POST',data,p.generation);pendingWrites.delete(id);await persistVault()}},{label:'Решить позже',value:null},{label:'Удалить локальное изменение',value:'discard',danger:true,run:async()=>{pendingWrites.delete(id);await persistVault()}}]});if(choice)await refresh()}
dataGroup.append(settingLink('Перенести фотографии в Storage','Закрытое хранилище · резерв для отката','archive',async()=>{if(!await glassConfirm('Перенести свои фотографии, аватар и фон в закрытое хранилище? Проверенные оригиналы останутся в отдельной резервной таблице для отката.','Перенести'))return;let after=0,copied=0,failed=0;try{for(let i=0;i<100;i++){const r=await api('media/migrate','POST',{after});copied+=r.copied;failed+=r.failed;if(r.next==null){await glassNotice('Перенесено изображений: '+copied+' · Ошибок: '+failed+'. Резервные оригиналы сохранены.');return}if(!Number.isSafeInteger(r.next)||r.next<=after)throw Error('Некорректная позиция');after=r.next}await glassNotice('Достигнут предел одного запуска. Исходные данные сохранены.')}catch(e){await glassNotice('Копирование остановлено: '+e.message+'. Оригиналы не удалены.')}}));
