function psPostpone(r){const d=psDialog('Перенести на…'),picker=node('input');picker.type='date';picker.value=psRange(r)?.[0]||psYmd(new Date());let busy=false;async function move(date){if(busy)return;if(!date)return;busy=true;try{const next=new Date(date+(r.ps_all_day?'T00:00:00Z':'T00:00:00')),old=r.due?new Date(r.due):null;if(old&&!r.ps_all_day)next.setHours(old.getHours(),old.getMinutes(),old.getSeconds(),old.getMilliseconds());const due=next.toISOString(),delta=old?+next-+old:0,patch={...r,due,reminder:r.reminder&&old?new Date(Date.parse(r.reminder)+delta).toISOString():r.reminder};if(r.ps_end)patch.ps_end=new Date(Date.parse(r.ps_end)+delta).toISOString();if(r.ps_reminders?.length)patch.ps_reminders=r.ps_reminders.map(x=>new Date(Date.parse(x)+delta).toISOString());if(r.ps_all_day){const days=(Date.parse(r.ps_end_day||r.ps_day)-Date.parse(r.ps_day))/86400000;patch.ps_day=date;const x=new Date(date+'T00:00:00Z');x.setUTCDate(x.getUTCDate()+days);patch.ps_end_day=x.toISOString().slice(0,10)}if(await coupleMutate('items/'+r.id,'PUT',patch))d.close()}finally{busy=false}}const now=new Date();const tomorrow=new Date(now);tomorrow.setDate(now.getDate()+1);const weekend=new Date(now);weekend.setDate(now.getDate()+((6-now.getDay()+7)%7||7));const monday=new Date(now);monday.setDate(now.getDate()+((8-now.getDay())%7||7));for(const [label,x] of [['Завтра',tomorrow],['В субботу',weekend],['Следующий понедельник',monday]])d.append(btn(label+' · '+x.toLocaleDateString('ru-RU'),()=>move(psYmd(x)),'secondary wide'));d.append(picker,btn('Перенести на выбранную дату',()=>move(picker.value),'wide'));if((r.repeat_rule||'none')==='none')d.append(btn('Без даты',async()=>{if(busy||!await glassConfirm('Убрать срок и связанные напоминания?','Убрать дату'))return;busy=true;try{if(await coupleMutate('items/'+r.id,'PUT',{...r,due:null,reminder:null,ps_reminders:[],ps_all_day:false,ps_day:null,ps_end_day:null,ps_end:null}))d.close()}finally{busy=false}},'secondary wide'));d.showModal()}
