function slInfo(raw){try{if(typeof raw!=='string'||!raw.trim()||/[\x00-\x20\\]/.test(raw.trim()))return null;const u=new URL(raw.trim());if(!['http:','https:'].includes(u.protocol)||u.username||u.password)return null;const key=(!u.port&&Object.keys(slProviders).find(k=>slProviders[k].hosts.includes(u.hostname)))||'other';return {key,host:u.hostname+(u.port?':'+u.port:''),url:u.href,name:slProviders[key]?.name||u.hostname+(u.port?':'+u.port:'')}}catch{return null}}
