async function psDiagnostics(){const d=psDialog('Диагностика'),rows=node('div',undefined,'ps-diagnostic'),check=btn('Проверить',async()=>{check.disabled=true;rows.replaceChildren(node('p','Проверка…','meta'));const data=[];data.push(['Интерфейс','1.1.3-rc.3']);try{const j=await api('diagnostics');data.push(['Авторизация и сервер','Ответ получен'],['Версия сервера',j.version||'Неизвестно'],['Схема',j.schema?.version||'Не подтверждена'],['Storage',j.storage==='configured'?'Настроено; чтение не проверено':'Не подтверждено'])}catch{data.push(['Сервер','Нет ответа'])}try{const j=await api('sync');data.push(['Синхронизация',j.revision!=null?'Ответ получен':'Нет ревизии'])}catch{data.push(['Синхронизация','Ошибка запроса'])}data.push(['Локальная офлайн-копия',vaultKey?'Разблокирована':'Не разблокирована'],['Ожидают отправки',String(pendingWrites.size)],['Ключ доступа',tg?.initData?'Режим Telegram':standalone?.desc()?.passkey?'Зарегистрирован; вход не проверен':'Не зарегистрирован'],['Push',typeof Notification==='undefined'?'Не поддерживается':'Разрешение: '+Notification.permission],['Резервное копирование','Проверить вручную'],['Доставка напоминаний','Проверить вручную']);rows.replaceChildren(...data.map(([k,v])=>{const r=node('div',undefined,'ps-diag-row');r.append(node('strong',k),node('small',v,'meta'));return r}));check.disabled=false},'wide');d.append(rows,check,node('p','Проверки только читают состояние; не выполняют отправку, восстановление или удаление данных.','meta'));d.showModal();await check.onclick()}
function psClearTransient(){psShoppingDraft={cat:null,title:'',qty:''};psExtraPhotoData=[];psPhotoSeq++;psPhotoCache.clear();psUpdateNotice?.remove();psUpdateNotice=null;psUpdateChecked=0;}

let psUpdateChecked=0,psUpdateNotice=null;async function psCheckUpdate(){if(Date.now()-psUpdateChecked<300000||!state.uid||!/^https?:$/.test(location.protocol))return;psUpdateChecked=Date.now();try{const res=await fetch(new URL('./index.html',location.href),{cache:'no-store'});if(!res.ok)return;const doc=new DOMParser().parseFromString(await res.text(),'text/html'),v=doc.querySelector('meta[name="planner-version"]')?.content;if(!v||v==='1.1.3-rc.3'||!/^\d+\.\d+\.\d+(?:-rc\.\d+)?$/.test(v)||!psNewer(v,'1.1.3-rc.3')||psUpdateNotice)return;const box=node('div',undefined,'entry ps-update');box.append(node('strong','Доступно обновление · '+v),btn('Обновить',async()=>{if(document.querySelector('dialog[open]')||pendingWrites.size||editorDrafts.size||settingsPending||settingsTimers.size||psShoppingDraft.title){await glassNotice('Сначала завершите редактирование и отправьте ожидающие изменения.');return}try{await (await navigator.serviceWorker?.getRegistration())?.update()}catch{}location.reload()},'secondary'),btn('Позже',()=>{box.remove()},'secondary'));$('error').after(box);psUpdateNotice=box}catch{}}
function psNewer(a,b){const split=v=>{const [core,rc]=v.split('-rc.');return [...core.split('.').map(Number),rc?Number(rc):Infinity]};const x=split(a),y=split(b);for(let i=0;i<x.length;i++){if(x[i]!==y[i])return x[i]>y[i]}return false}

if ('serviceWorker' in navigator && (location.protocol==='https:'||location.hostname==='localhost'))navigator.serviceWorker.register('./sw.js').catch(()=>{});
let pwaPollingStarted=false;
function launchPlanner(){if(!authorized())return;refresh();if(!pwaPollingStarted){pwaPollingStarted=true;setInterval(()=>{if(!authorized())return;refreshPlansDay();if(canPoll()){void pollChanges();void psCheckUpdate()}},SYNC_INTERVAL_MS)}}
if(standalone)standalone.start(launchPlanner,clearPwaLocal);else if(tg?.initData)launchPlanner();else{error('Откройте Cat’s planner кнопкой в Telegram.');if(!navigator.onLine&&localUid())void offerVaultUnlock();}
